import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {World} from '../world.js';import {installTownLife,lifeState} from '../townlife.js';import {installRegionalLife} from '../regional-life.js';import {HOUSEHOLDS} from '../townlife-content.js';import {npcRoute,advanceResident,residentActivity,localNpcAdvice} from '../npc-routines.js';import {civilianStyle,CIVILIAN_STYLES} from '../npc-art.js';
import {buildingReservations,pointInGroundRect} from '../environmental-grounding.js';
import {installTrailLife} from '../reconciled-travel.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
test('civilian art distinguishes named story people, professions and children without replacing the crew',()=>{assert.equal(CIVILIAN_STYLES.length,16);assert.equal(civilianStyle({}, {name:'Mara'}),0);assert.equal(civilianStyle({}, {name:'Nell'}),1);assert.equal(civilianStyle({type:'shop'},{name:'Merchant'}),7);for(const name of ['Sable','Iona','Rook','Brass','Riven','Mira','Veyr'])assert.equal(civilianStyle({}, {name}),null);for(const f of HOUSEHOLDS)for(let member=0;member<3;member++){const id=civilianStyle({family:f,member,name:f.names[member]}, {name:f.names[member]});assert.ok(id>=0&&id<16);if(member===2)assert.ok([1,12].includes(id));}});
test('residents route around another person and stop for conversations or nearby players',()=>{const scene={width:9,height:7,arrive:[1,1],floor:['#########','#.......#','#.......#','#.......#','#.......#','#.......#','#########'],doors:[],objects:[]},o={type:'npc',xy:[1,3]},other={type:'npc',xy:[4,3]};o.path=npcRoute(scene,o,[7,3],[o,other]);assert.ok(o.path.length);assert.ok(!o.path.some(p=>Math.floor(p[0])===4&&Math.floor(p[1])===3));const w={scene,state:{mode:'dialog',x:1.5,y:3.5}},before=[...o.xy];advanceResident(w,o,.1,[o,other]);assert.deepEqual(o.xy,before);w.state.mode='field';o.path=[[2.5,3.5]];w.state.x=2.2;w.state.y=3.5;advanceResident(w,o,.1,[o]);assert.deepEqual(o.xy,before);});
test('all household shifts remain on the authored floor with distinct initial placements',()=>{const w=new World(data);installTownLife(w);installRegionalLife(w);w.state.chapter=24;for(const f of HOUSEHOLDS){w.state.scene=f.scene;w.state.mode='field';const list=w.townLife.records();assert.equal(new Set(list.map(o=>o.xy.join(','))).size,list.length,f.id);const flags=JSON.stringify(w.state.flags),gold=w.state.gold;for(const minute of [360,480,720,840,1080,1320]){lifeState(w.state).minutes=minute;for(let i=0;i<30;i++)w.townLife.update(.1);for(const o of list.filter(o=>o.lifeKind==='resident'))assert.equal(w.scene.floor[Math.floor(o.xy[1]+.5)]?.[Math.floor(o.xy[0]+.5)],'.',f.id+' '+o.name);}assert.equal(JSON.stringify(w.state.flags),flags);assert.equal(w.state.gold,gold);}});
test('work descriptions reflect roles and local advice recommends a reachable rest site for a hurt crew',()=>{const family={roles:['oven keeper','letter carrier']};assert.notEqual(residentActivity({family,member:0},{name:'Morning'}),residentActivity({family,member:1},{name:'Morning'}));const camp={type:'camp',xy:[3,1]},shop={type:'shop',xy:[1,3]},w={activeHeroes:[{hp:1,maxHp:100}],scene:{floor:['#####','#...#','#...#','#...#','#####']},objects:()=>[camp,shop],done:()=>false};assert.equal(localNpcAdvice(w,{xy:[1,1]}),camp);});

test('a household conversation pauses its routine without deleting the return route',()=>{let dialog;const w=new World(data,{onDialog:d=>dialog=d});installTownLife(w);w.state.scene=5;w.state.chapter=24;w.state.mode='field';const o=w.townLife.records().find(o=>o.lifeKind==='resident'),route=[[o.xy[0]+.5,o.xy[1]+.5]];o.path=route;w.interact(o);assert.equal(w.state.mode,'dialog');assert.equal(o.path,route);dialog.choices.find(c=>c.label==='Wish them well').action();assert.equal(w.state.mode,'field');assert.equal(o.path,route);});

const beneathBuilding=(buildings,x,y)=>buildings.some(b=>b.groundRects.some(r=>pointInGroundRect(r,x,y))&&!pointInGroundRect(b.approach,x,y));
test('resident routes avoid projected building ground while real doorway approaches and player floor remain open',()=>{
 const scene={width:16,height:12,arrive:[2,5],floor:Array.from({length:12},(_,y)=>y===0||y===11?'#'.repeat(16):'#'+'.'.repeat(14)+'#'),doors:[],objects:[],exteriorBuildings:[{id:'house',projection:{outside:[7,6],scale:1,material:'home',kind:'building',bounds:{minX:-1,maxX:1,minY:-1,maxY:0},cells:[[-1,-1],[0,-1],[1,-1],[-1,0],[0,0],[1,0]]}}]},before=JSON.stringify(scene),buildings=buildingReservations(scene),walker={type:'npc',xy:[3,5]},path=npcRoute(scene,walker,[12,5],[walker]);
 assert.ok(path.length,'a real detour remains available');assert.ok(path.every(p=>!beneathBuilding(buildings,...p)));
 const visitor={type:'npc',xy:[7,9]},approach=npcRoute(scene,visitor,[7,6],[visitor]);assert.ok(approach.length);assert.deepEqual(approach.at(-1),[7.5,6.5]);
 assert.equal(scene.floor[5][7],'.');assert.equal(JSON.stringify(scene),before);
});
test('Cinderfall family shift routes remain below the facade instead of crossing its projected floor',()=>{
 const w=new World(data);installTrailLife(w);installTownLife(w);installRegionalLife(w);w.state.scene=5;w.state.chapter=24;w.state.mode='field';[w.state.x,w.state.y]=w.scene.arrive.map(n=>n+.5);w.objects();
 const floor=w.scene.floor.slice(),buildings=buildingReservations(w.scene);lifeState(w.state).minutes=480;w.townLife.update(0);
 const family=w.townLife.records().filter(o=>['Elsa','Tomas','Pip'].includes(o.name));assert.equal(family.length,3);
 for(const o of family){assert.ok(o.path.length||o.destination&&Math.hypot(o.xy[0]-o.destination[0],o.xy[1]-o.destination[1])<1.05,o.name+' is at or can reach the workplace');assert.ok(o.path.every(p=>!beneathBuilding(buildings,...p)),o.name+' crosses architecture');}
 assert.deepEqual(w.scene.floor,floor);
});
